<template>
  <section class="admission-exams">
    <div v-if="loadError" class="bio-nexus-message bio-nexus-message-error" role="alert">{{ loadError }}</div>
    <section class="exam-picker">
      <aside class="catalog-panel">
        <header class="panel-heading bio-nexus-panel-heading"><div class="bio-nexus-panel-heading-copy"><p class="bio-nexus-panel-eyebrow">Catálogo</p><h3 class="bio-nexus-panel-title">{{ panelTitle }}</h3></div><span>{{ visibleCount }}</span></header>
        <div class="mode-tabs"><button v-for="item in modes" :key="item.key" type="button" :class="{ active: mode === item.key }" @click="mode = item.key">{{ item.label }}</button></div>
