      </aside>
      <main class="selected-panel">
        <header class="panel-heading selected-heading bio-nexus-panel-heading"><div class="bio-nexus-panel-heading-copy"><p class="bio-nexus-panel-eyebrow">Orden del paciente</p><h3 class="bio-nexus-panel-title">Exámenes seleccionados</h3></div><BioNexusFormField class="tariff-control" label="Tarifa a cobrar" field-id="admission-tariff"><BioNexusSearchableSelect id="admission-tariff" :model-value="tariffId" :options="tariffOptions" value-key="id" label-key="displayName" search-placeholder="Buscar tarifa..." empty-text="Sin tarifas activas" @update:model-value="selectTariff" /></BioNexusFormField></header>
        <div class="selected-grid-shell">
          <BioNexusDataGrid
            v-if="modelValue.length"
            class="selected-exams-grid"
            :row-data="selectedGridRows"
            :column-defs="selectedColumnDefs"
            :default-col-def="selectedDefaultColDef"
            :components="selectedGridComponents"
            :get-row-id="getSelectedRowId"
            :pagination="false"
            :search-enabled="false"
            :refresh-enabled="false"
            :export-options="false"
            height="300px"
            dom-layout="normal"
            :min-grid-height="300"
            :max-grid-height="300"
          />
          <div v-else class="bio-nexus-empty-state selected-grid-empty">Agrega al menos un examen para continuar.</div>
        </div>
        <section class="rate-bar"><span>Tasa vigente</span><strong v-if="dollarValue">1 USD = {{ ves(rate) }}</strong><small v-if="dollarValue">{{ dollarValue.date || 'Fecha no disponible' }}</small><strong v-else>No disponible</strong></section>
        <section class="totals"><div class="exam-count-card"><span>Exámenes</span><strong>{{ examCount }}</strong></div><div class="discount-card"><label for="admission-discount">Descuento</label><span class="discount-input-wrap"><input id="admission-discount" v-model.number="discountPercent" class="bio-nexus-field discount-input" type="number" min="0" max="100" step="0.01" aria-label="Porcentaje de descuento"><b>%</b></span><small>{{ usd(discountAmount) }}</small></div><div><span>Subtotal</span><strong>{{ usd(summary.subtotal) }}</strong><small>{{ ves(summary.subtotal * rate) }}</small></div><div><span>Impuestos</span><strong>{{ usd(summary.taxTotal) }}</strong><small>{{ ves(summary.taxTotal * rate) }}</small></div><div class="grand"><span>Total</span><strong>{{ usd(finalTotal) }}</strong><small>{{ ves(finalTotal * rate) }}</small></div></section>
      </main>
    </section>
  </section>
</template>
<script setup>
import { computed, onMounted, ref, watch } from "vue";
import BioNexusFormField from "@/components/ui/BioNexusFormField.vue";
import BioNexusSearchableSelect from "@/components/ui/BioNexusSearchableSelect.vue";
import BioNexusDataGrid from "@/components/grid/BioNexusDataGrid.vue";
import BioNexusGridActionsCell from "@/components/grid/BioNexusGridActionsCell.vue";
import PatientAdmissionQuantityCell from "@/components/patients/PatientAdmissionQuantityCell.vue";
import { getExamGroups, getExamsByGroup, getTaxes } from "@/services/examCatalogService";
import { getRoutines } from "@/services/routinesService";
import { getCurrentDollarValue } from "@/services/dollarValueService";
import { resolveAdmissionTariff } from "@/services/patientAdmissionService";
import { formatRegionalMoney, formatRegionalNumber } from "@/services/regionalFormatter";
