const modes=[{key:"group",label:"Por grupo"},{key:"routine",label:"Rutinas"},{key:"search",label:"Buscar"}],resolvedTariff=ref(null),resolvedPrices=ref(new Map()),discountPercent=ref(0),mode=ref("group"),groups=ref([]),routines=ref([]),taxes=ref([]),catalog=ref([]),selectedGroupId=ref(null),search=ref(""),loading=ref(false),loadError=ref(""),dollarValue=ref(null);
const activeGroups=computed(()=>groups.value.filter(x=>!x.annulled)),selectedIds=computed(()=>new Set(props.modelValue.map(x=>Number(x.exam_catalog_id)))),available=computed(()=>catalog.value.filter(x=>!x.annulled&&!selectedIds.value.has(Number(x.id))));
const filteredAvailable=computed(()=>{const rows=mode.value==="group"?available.value.filter(x=>Number(x.group_id)===Number(selectedGroupId.value)):available.value,q=search.value.trim().toLocaleLowerCase();return rows.filter(x=>mode.value!=="search"||!q||`${x.description} ${x.abbreviation} ${x.group_description}`.toLocaleLowerCase().includes(q))});
const tariffOptions=computed(()=>props.tariffs.filter(x=>x.isActive!==false).map(x=>({...x,id:Number(x.id),displayName:`${x.name} (${x.code})`})));const availableRoutines=computed(()=>routines.value.filter(x=>routineAvailableCount(x)>0)),panelTitle=computed(()=>mode.value==="routine"?"Seleccionar rutinas":mode.value==="search"?"Buscar exámenes":"Seleccionar exámenes"),visibleCount=computed(()=>mode.value==="routine"?availableRoutines.value.length:filteredAvailable.value.length),rate=computed(()=>Number(dollarValue.value?.value)||0),examCount=computed(()=>props.modelValue.reduce((s,x)=>s+Number(x.amount||0),0));
const summary=computed(()=>props.modelValue.reduce((t,x)=>{t.subtotal+=Number(x.total)||0;t.taxTotal+=Number(x.tax_total)||0;t.total+=Number(x.total)||0;t.total+=Number(x.tax_total)||0;return t},{subtotal:0,taxTotal:0,total:0}));const normalizedDiscount=computed(()=>Math.max(0,Math.min(100,Number(discountPercent.value)||0))),discountAmount=computed(()=>round(summary.value.subtotal*normalizedDiscount.value/100)),finalTotal=computed(()=>round(summary.value.subtotal-discountAmount.value+summary.value.taxTotal));
