{field:"amount",headerName:"Cant.",width:72,minWidth:72,maxWidth:72,editable:false,cellClass:"selected-quantity-cell",headerClass:"selected-center-header",cellRenderer:"PatientAdmissionQuantityCell",cellRendererParams:{onChange:(row,value)=>setQuantity(row,value)}},
{field:"description",headerName:"Descripción",minWidth:150,flex:1.7,valueGetter:params=>`${params.data?.description||""}${params.data?.abbreviation?` · ${params.data.abbreviation}`:""}`},
{field:"tax_description",headerName:"Impuesto",minWidth:118,flex:.9,valueGetter:params=>`${params.data?.tax_description||"Exo"} · ${number(params.data?.tax_amount||0)}%`},
{field:"price",headerName:"Precio USD",minWidth:94,flex:.7,valueFormatter:params=>usd(params.value),cellClass:"selected-money-cell",headerClass:"selected-money-header"},
{field:"total",headerName:"Total USD",minWidth:94,flex:.7,valueFormatter:params=>usd(params.value),cellClass:"selected-total-cell",headerClass:"selected-money-header"},
{colId:"actions",headerName:"Acciones",width:72,minWidth:72,maxWidth:72,suppressMovable:true,sortable:false,filter:false,resizable:false,headerClass:"bio-nexus-grid-actions-header",cellClass:"bio-nexus-grid-actions-cell",cellRenderer:"BioNexusGridActionsCell",cellRendererParams:{actions:[{key:"remove",label:"Quitar",icon:"delete",variant:"danger",onClick:row=>removeExam(row.exam_catalog_id)}]}}
]);
