function round(v){return Math.round((Number(v)+Number.EPSILON)*100)/100}function price(exam){return Number(resolvedPrices.value.get(Number(exam.id)))||0}function tax(exam){return taxes.value.find(x=>Number(x.id)===Number(exam.tax_id))||{description:"Exo",value:0}}function routineAvailableCount(r){return(r.registered_exams||[]).filter(x=>x.active!==false&&!selectedIds.value.has(Number(x.examId))).length}
function make(exam,amount=1){const selectedTax=tax(exam),unit=round(price(exam)),quantity=Math.max(1,Math.min(99,Number(amount)||1)),line=round(unit*quantity),taxTotal=round(line*(Number(selectedTax.value)||0)/100);return{exam_catalog_id:Number(exam.id),examlistsId:Number(exam.id),group_id:Number(exam.group_id),position:Number(exam.position)||0,description:exam.description,abbreviation:exam.abbreviation,amount:quantity,price:unit,total:line,tax_description:selectedTax.description||"Exo",tax_amount:Number(selectedTax.value)||0,tax_total:taxTotal,size:Number(exam.size)||1,status:0}}
