function usd(v){return `$ ${formatRegionalNumber(v,settings.settings,{minimumFractionDigits:2,maximumFractionDigits:2})}`}function ves(v){return formatRegionalMoney(v,settings.settings)}function number(v){return formatRegionalNumber(v,settings.settings,{minimumFractionDigits:2,maximumFractionDigits:2})}
